import java.util.Stack; // presente no arquivo
public static int inverte(int num) {
  Stack<Integer> pilha = new Stack<Integer>();
  do {
    int resto = num % 10;
    num /= 10;
    pilha.push(resto);
  } while(num > 0);
  for (int i=1; ! pilha.isEmpty(); i*=10)
    num += pilha.pop() * i;
  return num;
}

